    exit;
}

/**
 * Function to clear Nginx cache on theme/plugin changes
 */
function clear_nginx_cache_on_changes() {
    // Check if the current action is 'activate' and the post type is either 'theme' or 'plugin'
    if (isset($_GET['action']) && $_GET['action'] === 'activate' && in_array(get_post_type(), ['theme', 'plugin'])) {
        // Get the post ID from the URL
        $post_id = isset($_GET['post']) ? absint($_GET['post']) : null;

        // If a specific post ID is provided, use it; otherwise, clear the cache for all themes/plugins
        if ($post_id) {
            $post = get_post($post_id);
            if ($post && in_array($post->post_type, ['theme', 'plugin'])) {
                clear_nginx_helper_cache($post_id);
            }
        } else {
            clear_nginx_helper_cache();
        }
    }
}

/**
 * Function to clear Nginx helper cache for a specific post
 *
 * @param int $post_id The ID of the post (theme or plugin)
 */
function clear_nginx_helper_cache($post_id = null) {
    global $wpdb;

    // Construct the SQL query to delete entries from the wp_nginx_helper_cache table
    $query = "DELETE FROM {$wpdb->prefix}nginx_helper_cache WHERE post_id = %d OR post_id IS NULL";

    // Execute the query with the appropriate parameters
    $wpdb->query($wpdb->prepare($query, $post_id));
}

// Hook into the 'activated_plugin' and 'activated_theme' actions
add_action('activated_plugin', 'clear_nginx_cache_on_changes');
add_action('activated_theme', 'clear_nginx_cache_on_changes');

// Hook into the 'deactivate_plugins' and 'switch_theme' actions
add_action('deactivate_plugins', 'clear_nginx_cache_on_changes');
add_action('switch_theme', 'clear_nginx_cache_on_changes');
```

### Step 2: Activate the Plugin

1. Log in to your WordPress admin dashboard.
2. Navigate to **Plugins** > **Installed Plugins**.
3. Find the plugin named "Clear Nginx Cache on Theme/Plugin Changes".
4. Click the **Activate** button.

### Explanation

The plugin uses WordPress hooks (`activated_plugin`, `activated_theme`, `deactivate_plugins`, and `switch_theme`) to detect when a theme or plugin is activated, deactivated, or switched. When one of these events occurs, it checks if the action is `'activate'` and if the post type is either `'theme'` or `'plugin'`. If so, it retrieves the post ID from the URL and clears the Nginx helper cache for that specific post or for all themes/plugins if no specific post ID is provided.

This approach ensures that the Nginx helper cache is cleared whenever a theme or plugin is added, updated, or changed, improving performance by removing stale cached data.

