To generate SV (SystemVerilog) constraints ensuring that the number of transitions from the previous output is exactly 5, you can use a combination of `posedge` and `negedge` events along with counters or state machines. Here's an example:

```systemverilog
module testbench;
    reg clk = 0;
    reg rst_n = 1;
    wire [31:0] data_out;

    // Clock generation
    always #5 clk = ~clk;

    // Reset
    initial begin
        rst_n = 0;
        #20;
        rst_n = 1;
    end

    // State machine to count transitions
    typedef enum logic [2:0] {
        IDLE,
        TRANSITION_1,
        TRANSITION_2,
        TRANSITION_3,
        TRANSITION_4,
        TRANSITION_5
    } state_t;

    state_t current_state, next_state;

    // Counters for each transition
    integer counter [6];

    // FSM to manage transitions
    initial begin
        current_state = IDLE;
        for (integer i = 0; i < 6; i++) begin
            counter[i] = 0;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_state <= IDLE;
            for (integer i = 0; i < 6; i++) begin
                counter[i] <= 0;
            end
        end else begin
            case (current_state)
                IDLE: begin
                    if (data_out != 32'b0) begin
                        current_state <= TRANSITION_1;
                        counter[0] <= 1;
                    end
                end
                TRANSITION_1: begin
                    if (data_out == 32'b0) begin
                        current_state <= TRANSITION_2;
                        counter[1] <= 1;
                    end
                end
                TRANSITION_2: begin
                    if (data_out == 32'b1) begin
                        current_state <= TRANSITION_3;
                        counter[2] <= 1;
                    end
                end
                TRANSITION_3: begin
                    if (data_out == 32'b2) begin
                        current_state <= TRANSITION_4;
                        counter[3] <= 1;
                    end
                end
                TRANSITION_4: begin
                    if (data_out == 32'b3) begin
                        current_state <= TRANSITION_5;
                        counter[4] <= 1;
                    end
                end
                TRANSITION_5: begin
                    if (data_out == 32'b4) begin
                        current_state <= IDLE;
                        counter[5] <= 1;
                    end
                end
            endcase
        end
    end

    // Generate random data out
    initial begin
        forever begin
            data_out = $random % 5;
            #10;
        end
    end
endmodule
```

In this code:
- A simple state machine (`state_t`) manages the transitions.
- Counters (`counter`) keep track of how many times each transition has occurred.
- The `always` block updates the state based on the value of `data_out`.
- When all five transitions have been completed, the state returns to `IDLE`.

This setup ensures that there will be exactly five transitions before returning to the idle state. Note that this is a basic implementation and may need adjustments depending on your specific requirements.

