### Step 1: Create the `FavoritesManager` Class

This class will handle adding and removing favorite business names based on whether the user is logged in or not.

```php
// App/Favorites/FavoritesManager.php

namespace App\Favorites;

use App\Models\User;
use App\Models\Favorite;
use Illuminate\Http\Request;

class FavoritesManager
{
    public function addToFavorites(Request $request, string $businessName)
    {
        if (Auth::check()) {
            // If authenticated, save to database
            $user = Auth::user();
            $favorite = Favorite::firstOrCreate([
                'user_id' => $user->id,
                'name' => $businessName,
            ]);
            return response()->json(['message' => 'Added to favorites', 'favorite' => $favorite]);
        } else {
            // If not authenticated, save to session
            session()->put('favorites.' . $businessName, true);
            return response()->json(['message' => 'Added to favorites (session)', 'status' => 'success']);
        }
    }

    public function removeFromFavorites(Request $request, string $businessName)
    {
        if (Auth::check()) {
            // If authenticated, delete from database
            $user = Auth::user();
            $favorite = Favorite::where('user_id', $user->id)->where('name', $businessName)->first();
            if ($favorite) {
                $favorite->delete();
                return response()->json(['message' => 'Removed from favorites', 'status' => 'success']);
            } else {
                return response()->json(['message' => 'Favorite not found'], 404);
            }
        } else {
            // If not authenticated, remove from session
            if (session()->has('favorites.' . $businessName)) {
                session()->forget('favorites.' . $businessName);
                return response()->json(['message' => 'Removed from favorites (session)', 'status' => 'success']);
            } else {
                return response()->json(['message' => 'Favorite not found (session)'], 404);
            }
        }
    }
}
```

