        buffer.writeUInt16BE(this.tcpHeader.destinationPort, offset + 2);
        buffer.writeInt32BE(this.tcpHeader.sequenceNumber, offset + 4);
        buffer.writeInt32BE(this.tcpHeader.acknowledgmentNumber, offset + 8);
