```typescript
// Define the sigmoid activation function
function sigmoid(x: number): number {
    return 1 / (1 + Math.exp(-x));
}

// Define the derivative of the sigmoid function
function sigmoidDerivative(x: number): number {
    return x * (1 - x);
}

// Simple RNN class
class SimpleRNN {
    private weightsInputToHidden: number[][];
    private weightsHiddenToOutput: number[];
    private biasHidden: number;
    private biasOutput: number;

    constructor(inputSize: number, hiddenSize: number) {
        // Initialize weights and biases with random values
        this.weightsInputToHidden = Array.from({ length: inputSize }, () =>
            Array(hiddenSize).fill(0.01)
        );
        this.weightsHiddenToOutput = Array(hiddenSize).fill(0.01);
        this.biasHidden = 0.01;
        this.biasOutput = 0.01;
    }

    // Forward pass through the RNN
    public forward(inputs: number[]): number[] {
        const hiddenStates: number[][] = [];
        let currentHiddenState: number[] = [];

        inputs.forEach((input, index) => {
            if (index === 0) {
                // Initial hidden state can be zero or learned from data
                currentHiddenState = [0];
            } else {
                // Update hidden state using the previous hidden state
                currentHiddenState = this.updateHiddenState(currentHiddenState, input);
            }

            // Compute output using the current hidden state
            const output = this.computeOutput(currentHiddenState);
            hiddenStates.push(currentHiddenState.slice());
        });

        return hiddenStates;
    }

    // Update hidden state using tanh activation function
    private updateHiddenState(hiddenState: number[], input: number): number[] {
        const weightedSum = hiddenState.reduce((sum, weight, i) => sum + weight * this.weightsInputToHidden[i][input], 0) +
                            this.biasHidden;
        return [Math.tanh(weightedSum)];
    }

    // Compute output using linear activation function
    private computeOutput(hiddenState: number[]): number {
        const weightedSum = hiddenState.reduce((sum, weight, i) => sum + weight * this.weightsHiddenToOutput[i], 0) +
                             this.biasOutput;
        return weightedSum;
    }
}

// Example usage
const rnn = new SimpleRNN(3, 2); // Input size 3, Hidden size 2

const inputs = [1, 0, 1]; // Example input sequence
const outputs = rnn.forward(inputs);

console.log("Outputs:", outputs);
```

