import { useQuery } from '@tanstack/vue-query';

// Create a global Pinia store instance
const pinia = createPinia();

// Define your Pinia store state
const useSessionStore = defineStore('session', {
  state: () => ({
    sessionData: null,
  }),
  actions: {
    async fetchSession() {
      const query = useQuery({
        queryKey: ['session'],
        queryFn: async () => {
          // Fetch data from /get_session endpoint
          const response = await fetch('/get_session');
          return response.json();
        },
        staleTime: 60 * 1000, // Cache for 1 minute
      });

      // Update the store with only the selected keys
      if (query.data) {
        this.sessionData = {
          id: query.data.id,
          name: query.data.name,
          email: query.data.email,
        };
      }
    },
  },
});

